// src/components/KnowYourCandidate.js
import React, { useState } from 'react';

const KnowYourCandidate = ({ user, language }) => {
  const [candidateInfo, setCandidateInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [constituency, setConstituency] = useState(user?.constituency || '');

  const fetchCandidateInfo = async () => {
    if (!constituency) {
      setError(language === 'hindi' 
        ? 'कृपया पहले अपना निर्वाचन क्षेत्र सेट करें' 
        : 'Please set your constituency first'
      );
      return;
    }

    setLoading(true);
    setError('');
    setCandidateInfo(null);

    try {
      // Use a reliable external API for election data
      const response = await fetch(`https://api.example.com/candidates/${constituency}`);
      // Note: Replace with actual election API if available
      
      // For now, we'll use comprehensive static data
      const candidates = getStaticCandidateData(constituency);
      
      // Filter based on search query
      const filteredCandidates = searchQuery 
        ? candidates.filter(candidate => 
            candidate.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            candidate.party.toLowerCase().includes(searchQuery.toLowerCase())
          )
        : candidates;
        
      setCandidateInfo(filteredCandidates);
      setLoading(false);
      
    } catch (error) {
      console.error('Error:', error);
      // Use static data as fallback
      const candidates = getStaticCandidateData(constituency);
      setCandidateInfo(candidates);
      setError(language === 'hindi' 
        ? 'लाइव डेटा उपलब्ध नहीं, संग्रहीत जानकारी दिखाई जा रही है' 
        : 'Live data unavailable, showing stored information'
      );
      setLoading(false);
    }
  };

  // Comprehensive static candidate data
  const getStaticCandidateData = (constituency) => {
    const candidateDatabase = {
      'Pune': [
        {
          name: 'मुरलीधर मोहोल / Murlidhar Mohol',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'बैचलर ऑफ आर्ट्स, पुणे विश्वविद्यालय',
